# Simple version: r % 6 for all rows, no special handling for row 6

# Pattern 6x3
pattern_6x3 = [
    [2, 3, 2],  # row 0
    [2, 2, 2],  # row 1
    [2, 2, 9],  # row 2
    [2, 2, 2],  # row 3
    [2, 9, 2],  # row 4
    [3, 2, 2],  # row 5
]

final_output = []
for r in range(13):
    row = []
    for c in range(11):
        if c in [3, 7]:
            row.append(6)  # vertical bars
        else:
            row.append(pattern_6x3[r % 6][c % 3])
    final_output.append(row)

print("Final output (simple version, r % 6):")
for row in final_output:
    print(row)

print("\nSpecial positions:")
for row in final_output:
    for c, val in enumerate(row):
        if val not in [2, 6]:
            print(f"({final_output.index(row)}, {c}): {val}")
